
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;
CREATE TABLE public.user_profile(id uuid PRIMARY KEY,auth_user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE RESTRICT,display_name text,account_status text NOT NULL DEFAULT 'active' CHECK(account_status IN ('active','deletion_pending','disabled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE TABLE public.user_preference(id uuid PRIMARY KEY,user_id uuid NOT NULL UNIQUE REFERENCES public.user_profile(id) ON DELETE RESTRICT,time_zone text NOT NULL DEFAULT 'America/Havana',language text NOT NULL DEFAULT 'es',preferences jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(preferences)='object'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE TABLE public.life_area(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 160),description text,position int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused')),archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,owner_user_id),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE UNIQUE INDEX life_area_title_uq ON public.life_area(owner_user_id,lower(title)) WHERE deleted_at IS NULL;
CREATE TABLE public.goal(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,life_area_id uuid NOT NULL,title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 200),expected_result text,reason text,target_date date,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','completed','cancelled')),archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(life_area_id,owner_user_id) REFERENCES public.life_area(id,owner_user_id) ON DELETE RESTRICT,CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.subgoal(id uuid PRIMARY KEY,goal_id uuid NOT NULL REFERENCES public.goal(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 200),expected_result text,target_date date,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','completed','cancelled')),archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.project(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 200),purpose text,status text NOT NULL DEFAULT 'planning' CHECK(status IN ('planning','active','paused','completed','cancelled')),start_date date,target_date date,archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(target_date IS NULL OR start_date IS NULL OR target_date>=start_date),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.task(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,assignee_user_id uuid REFERENCES public.user_profile(id) ON DELETE RESTRICT,action text NOT NULL CHECK(length(btrim(action)) BETWEEN 1 AND 240),description text,status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','blocked','completed','cancelled')),priority smallint NOT NULL DEFAULT 3 CHECK(priority BETWEEN 1 AND 5),due_date date,due_at timestamptz,time_zone text NOT NULL DEFAULT 'America/Havana',estimated_duration_minutes int CHECK(estimated_duration_minutes BETWEEN 1 AND 10080),completed_at timestamptz,completion_outcome text CHECK(completion_outcome IN ('complete','partial_progress','blocked','no_longer_applicable')),archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(assignee_user_id IS NULL OR assignee_user_id=owner_user_id),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.task_project_link(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES public.task(id) ON DELETE RESTRICT,project_id uuid NOT NULL REFERENCES public.project(id) ON DELETE RESTRICT,relation_role text NOT NULL DEFAULT 'additional' CHECK(relation_role IN ('primary','additional')),created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(task_id,project_id),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE UNIQUE INDEX task_project_primary_uq ON public.task_project_link(task_id) WHERE relation_role='primary';
CREATE TABLE public.contribution_relation(id uuid PRIMARY KEY,project_id uuid REFERENCES public.project(id) ON DELETE RESTRICT,task_id uuid REFERENCES public.task(id) ON DELETE RESTRICT,goal_id uuid REFERENCES public.goal(id) ON DELETE RESTRICT,subgoal_id uuid REFERENCES public.subgoal(id) ON DELETE RESTRICT,relation_status text NOT NULL DEFAULT 'suggested' CHECK(relation_status IN ('suggested','confirmed','rejected','removed')),created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(project_id,task_id)=1),CHECK(num_nonnulls(goal_id,subgoal_id)=1),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE UNIQUE INDEX contribution_pg_uq ON public.contribution_relation(project_id,goal_id) WHERE project_id IS NOT NULL AND goal_id IS NOT NULL;
CREATE UNIQUE INDEX contribution_ps_uq ON public.contribution_relation(project_id,subgoal_id) WHERE project_id IS NOT NULL AND subgoal_id IS NOT NULL;
CREATE UNIQUE INDEX contribution_tg_uq ON public.contribution_relation(task_id,goal_id) WHERE task_id IS NOT NULL AND goal_id IS NOT NULL;
CREATE UNIQUE INDEX contribution_ts_uq ON public.contribution_relation(task_id,subgoal_id) WHERE task_id IS NOT NULL AND subgoal_id IS NOT NULL;
CREATE TABLE public.capture(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,input_type text NOT NULL DEFAULT 'text' CHECK(input_type IN ('text','voice','file','import')),content_original text NOT NULL CHECK(length(btrim(content_original))>0),captured_at timestamptz NOT NULL DEFAULT now(),processing_status text NOT NULL DEFAULT 'not_started' CHECK(processing_status IN ('not_started','queued','processing','processed','failed')),attention_status text NOT NULL DEFAULT 'needs_review' CHECK(attention_status IN ('needs_review','reviewed','archived')),sync_status text NOT NULL DEFAULT 'synced' CHECK(sync_status IN ('pending','synced','conflict','failed')),deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.capture_part(id uuid PRIMARY KEY,capture_id uuid NOT NULL REFERENCES public.capture(id) ON DELETE RESTRICT,part_index int NOT NULL CHECK(part_index>=0),original_fragment text NOT NULL CHECK(length(btrim(original_fragment))>0),interpretation text,category text CHECK(category IN ('task','event','request','habit','goal_subgoal','project','note_idea','list')),review_status text NOT NULL DEFAULT 'unreviewed' CHECK(review_status IN ('unreviewed','accepted','edited','rejected')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(capture_id,part_index),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE TABLE public.processing_run(id uuid PRIMARY KEY,capture_id uuid NOT NULL REFERENCES public.capture(id) ON DELETE RESTRICT,processor_version text NOT NULL,status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','succeeded','retryable','failed')),attempt_number int NOT NULL DEFAULT 1 CHECK(attempt_number>0),idempotency_key text NOT NULL,result jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(result)='object'),error_code text,error_message text,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(capture_id,idempotency_key),CHECK(finished_at IS NULL OR finished_at>=started_at),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE TABLE public.note_idea(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,kind text NOT NULL CHECK(kind IN ('note','idea')),title text,content text NOT NULL CHECK(length(btrim(content))>0),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.user_list(id uuid PRIMARY KEY,owner_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,created_by_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 200),purpose text,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),archived_at timestamptz,deleted_at timestamptz,purge_after timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128),CHECK((deleted_at IS NULL AND purge_after IS NULL) OR purge_after=deleted_at+interval '30 days'));
CREATE TABLE public.list_item(id uuid PRIMARY KEY,list_id uuid NOT NULL REFERENCES public.user_list(id) ON DELETE RESTRICT,task_id uuid REFERENCES public.task(id) ON DELETE RESTRICT,content text NOT NULL CHECK(length(btrim(content)) BETWEEN 1 AND 500),position int NOT NULL DEFAULT 0,is_checked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE TABLE public.capture_link(id uuid PRIMARY KEY,capture_part_id uuid NOT NULL REFERENCES public.capture_part(id) ON DELETE RESTRICT,task_id uuid REFERENCES public.task(id) ON DELETE RESTRICT,goal_id uuid REFERENCES public.goal(id) ON DELETE RESTRICT,subgoal_id uuid REFERENCES public.subgoal(id) ON DELETE RESTRICT,project_id uuid REFERENCES public.project(id) ON DELETE RESTRICT,note_idea_id uuid REFERENCES public.note_idea(id) ON DELETE RESTRICT,user_list_id uuid REFERENCES public.user_list(id) ON DELETE RESTRICT,list_item_id uuid REFERENCES public.list_item(id) ON DELETE RESTRICT,link_status text NOT NULL DEFAULT 'suggested' CHECK(link_status IN ('suggested','confirmed','rejected')),confidence numeric(4,3) CHECK(confidence BETWEEN 0 AND 1),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(task_id,goal_id,subgoal_id,project_id,note_idea_id,user_list_id,list_item_id)=1),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE TABLE public.audit_event(id uuid PRIMARY KEY,account_user_id uuid NOT NULL REFERENCES public.user_profile(id) ON DELETE RESTRICT,actor_user_id uuid REFERENCES public.user_profile(id) ON DELETE RESTRICT,action text NOT NULL,entity_type text NOT NULL,entity_id uuid,result text NOT NULL DEFAULT 'success' CHECK(result IN ('success','failure','denied','pending')),source text NOT NULL DEFAULT 'user' CHECK(source IN ('user','system','ai')),correlation_id uuid,details jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(details)='object'),occurred_at timestamptz NOT NULL DEFAULT now(),recorded_at timestamptz NOT NULL DEFAULT now(),CHECK((get_byte(uuid_send(id),6)>>4)=7 AND (get_byte(uuid_send(id),8)&192)=128));
CREATE INDEX audit_event_account_time_idx ON public.audit_event(account_user_id,occurred_at DESC);

DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['user_profile','user_preference','life_area','goal','subgoal','project','task','task_project_link','contribution_relation','capture','capture_part','processing_run','note_idea','user_list','list_item','capture_link','audit_event']
 LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP;
END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA public TO authenticated;
